window.__qzParts=window.__qzParts||{};window.__qzParts.congnghe=[{"p":"Vai trò quan trọng nhất của nhà ở đối với mỗi gia đình là gì?","o":["Là nơi ở, sinh hoạt và sum họp của các thành viên trong gia đình","Là nơi để xe và chứa đồ cũ","Là nơi chỉ để tiếp khách","Là nơi kinh doanh, buôn bán"],"a":"Là nơi ở, sinh hoạt và sum họp của các thành viên trong gia đình","h":"Hãy nghĩ đến nơi các thành viên trong gia đình sống cùng nhau mỗi ngày.","e":"Nhà ở là nơi các thành viên trong gia đình cùng sinh sống, sinh hoạt, nghỉ ngơi và sum họp sau mỗi ngày.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vật liệu nào thường được dùng để xây tường nhà?","o":["Vải bạt","Gạch","Giấy các-tông","Lá cây khô"],"a":"Gạch","h":"Đây là vật liệu nung từ đất sét, rất phổ biến ở các công trình nhà ở.","e":"Gạch (gạch nung hoặc gạch không nung) kết hợp với vữa xi măng là vật liệu phổ biến nhất để xây tường nhà ở nước ta.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khu vực nào trong nhà thường dùng để nấu ăn?","o":["Phòng ngủ","Phòng khách","Khu vực bếp","Phòng vệ sinh"],"a":"Khu vực bếp","h":"Đây là nơi đặt bếp nấu và chuẩn bị thức ăn.","e":"Khu vực bếp là nơi nấu nướng và chuẩn bị thức ăn cho gia đình, thường bố trí gần khu vực ăn uống.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Nhà ở thông minh có đặc điểm nổi bật nào?","o":["Được sơn rất nhiều màu sắc","Có thật nhiều cửa sổ lớn","Được xây bằng vật liệu đắt tiền nhất","Các thiết bị trong nhà có thể điều khiển tự động hoặc từ xa, tiện nghi và tiết kiệm năng lượng"],"a":"Các thiết bị trong nhà có thể điều khiển tự động hoặc từ xa, tiện nghi và tiết kiệm năng lượng","h":"Hãy nghĩ đến việc bật tắt đèn, điều hòa bằng điện thoại từ xa.","e":"Nhà ở thông minh ứng dụng công nghệ để điều khiển đèn, điều hòa, rèm cửa... tự động hoặc từ xa, giúp cuộc sống tiện nghi và tiết kiệm năng lượng.","t":"cn-lop6","g":6,"l":"thu-thach"},{"p":"Một ngôi nhà ở tốt cần đáp ứng yêu cầu cơ bản nào?","o":["Chắc chắn, an toàn và thuận tiện cho sinh hoạt của gia đình","Càng cao nhiều tầng càng tốt","Chỉ cần đẹp là đủ","Càng rộng thì càng tốt, không cần chắc chắn"],"a":"Chắc chắn, an toàn và thuận tiện cho sinh hoạt của gia đình","h":"Nhà trước hết phải bảo vệ được người ở bên trong.","e":"Nhà ở cần được xây dựng chắc chắn, bền vững, đảm bảo an toàn, đồng thời thuận tiện và thoải mái cho sinh hoạt hằng ngày.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khu vực sinh hoạt chung của gia đình trong nhà thường là khu vực nào?","o":["Phòng vệ sinh","Phòng khách","Nhà kho","Ban công"],"a":"Phòng khách","h":"Đây là nơi gia đình tiếp khách và quây quần xem ti vi.","e":"Phòng khách là khu vực sinh hoạt chung, nơi gia đình tiếp khách, trò chuyện và sum họp.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vải sợi thiên nhiên được làm từ nguồn nguyên liệu nào?","o":["Từ dầu mỏ","Từ nhựa tái chế","Từ thực vật và động vật như bông, tơ tằm, len","Từ sợi kim loại"],"a":"Từ thực vật và động vật như bông, tơ tằm, len","h":"Sợi thiên nhiên có sẵn trong tự nhiên, từ cây cỏ hoặc động vật.","e":"Vải sợi thiên nhiên được dệt từ sợi có trong tự nhiên: sợi bông từ cây bông, tơ tằm từ kén tằm, len từ lông cừu.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vải sợi hoá học thường có đặc điểm nào?","o":["Chỉ may được trang phục một màu","Rất dễ rách và nhanh hỏng","Thấm hút mồ hôi tốt hơn mọi loại vải thiên nhiên","Ít bị nhàu, bền, giá thành thường thấp hơn vải thiên nhiên"],"a":"Ít bị nhàu, bền, giá thành thường thấp hơn vải thiên nhiên","h":"Sợi hoá học do con người tạo ra trong nhà máy.","e":"Vải sợi hoá học do con người tạo ra, thường ít nhàu, bền, màu sắc đa dạng và giá thành thấp, nhưng thoáng mát kém hơn vải thiên nhiên.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi lựa chọn trang phục đi học, em cần chú ý điều gì?","o":["Trang phục phù hợp với lứa tuổi, hoàn cảnh và quy định của nhà trường","Trang phục càng đắt tiền càng tốt","Trang phục phải theo mốt mới nhất","Trang phục phải giống hệt của bạn bè"],"a":"Trang phục phù hợp với lứa tuổi, hoàn cảnh và quy định của nhà trường","h":"Trang phục đi học cần gọn gàng, đúng quy định của trường.","e":"Trang phục đi học cần phù hợp lứa tuổi, gọn gàng, lịch sự và tuân thủ quy định của nhà trường, không nên chạy theo mốt hay giá tiền.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Cách bảo quản trang phục nào là đúng?","o":["Giặt chung tất cả các màu với nhau","Giặt sạch, phơi nơi thoáng, là (ủi) và cất ở nơi khô ráo","Để quần áo còn ẩm trong tủ kín","Vò thật mạnh mọi loại vải khi giặt"],"a":"Giặt sạch, phơi nơi thoáng, là (ủi) và cất ở nơi khô ráo","h":"Quần áo ẩm mốc là do cất giữ nơi ẩm ướt.","e":"Trang phục cần giặt sạch, phơi ở nơi thoáng mát, là (ủi) cho phẳng và cất giữ ở nơi khô ráo để tránh ẩm mốc, hư hỏng.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trước khi là (ủi) quần áo, em cần lưu ý điều gì?","o":["Luôn để bàn là ở mức nhiệt cao nhất","Không cần kiểm tra gì, cứ là thật nhanh","Xem hướng dẫn trên nhãn quần áo và chọn nhiệt độ phù hợp với từng loại vải","Chỉ là quần áo khi còn ướt sũng"],"a":"Xem hướng dẫn trên nhãn quần áo và chọn nhiệt độ phù hợp với từng loại vải","h":"Mỗi loại vải chịu được một mức nhiệt khác nhau.","e":"Mỗi loại vải chịu nhiệt khác nhau. Xem nhãn hướng dẫn và chỉnh nhiệt độ bàn là phù hợp giúp không làm cháy, hỏng quần áo.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vải bông (cotton) được dệt từ sợi bông nên thuộc loại vải nào?","o":["Vải sợi hoá học","Vải sợi tổng hợp","Vải sợi pha","Vải sợi thiên nhiên"],"a":"Vải sợi thiên nhiên","h":"Sợi bông lấy từ quả bông, một loại cây trồng.","e":"Sợi bông được lấy từ cây bông trong tự nhiên nên vải bông thuộc nhóm vải sợi thiên nhiên, có ưu điểm mềm, thấm hút mồ hôi tốt.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Chất đạm có nhiều trong nhóm thực phẩm nào?","o":["Thịt, cá, trứng, sữa và các loại đậu","Cơm, bánh mì, khoai","Rau xanh và trái cây","Dầu ăn và mỡ động vật"],"a":"Thịt, cá, trứng, sữa và các loại đậu","h":"Chất đạm giúp cơ thể lớn lên và khỏe mạnh.","e":"Chất đạm (protein) có nhiều trong thịt, cá, trứng, sữa và các loại đậu, giúp xây dựng và phát triển cơ thể.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Nhóm chất bột, đường (như cơm, bánh mì, khoai) chủ yếu cung cấp cho cơ thể điều gì?","o":["Chất xơ","Năng lượng cho cơ thể hoạt động","Vitamin C","Canxi"],"a":"Năng lượng cho cơ thể hoạt động","h":"Đây là \"nhiên liệu\" chính giúp cơ thể hoạt động cả ngày.","e":"Chất bột, đường trong cơm, bánh mì, khoai, ngô là nguồn cung cấp năng lượng chính cho mọi hoạt động của cơ thể.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Cách bảo quản thực phẩm trong tủ lạnh nào là đúng?","o":["Để thịt sống chung với rau ăn sống","Để thực phẩm ngoài trời nắng cho khô","Đậy kín thực phẩm, để thực phẩm sống và chín ở các ngăn riêng","Không cần đậy nắp hộp đựng thực phẩm"],"a":"Đậy kín thực phẩm, để thực phẩm sống và chín ở các ngăn riêng","h":"Thực phẩm sống có thể làm lây bẩn sang thực phẩm chín.","e":"Thực phẩm trong tủ lạnh cần được đậy kín và để thực phẩm sống, chín ở các ngăn riêng để tránh nhiễm bẩn chéo và giữ được lâu.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Để chế biến món ăn đảm bảo an toàn vệ sinh, em cần làm gì?","o":["Không cần rửa tay trước khi nấu ăn","Dùng chung một thớt cho cả thịt sống và thức ăn chín","Nếm thử thịt sống để kiểm tra gia vị","Rửa tay sạch trước khi chế biến và nấu chín kĩ thức ăn"],"a":"Rửa tay sạch trước khi chế biến và nấu chín kĩ thức ăn","h":"Vệ sinh phải được thực hiện từ khâu chuẩn bị đến khi nấu xong.","e":"Rửa tay sạch trước khi chế biến, dùng dụng cụ sạch và nấu chín kĩ thức ăn giúp phòng tránh ngộ độc thực phẩm.","t":"cn-lop6","g":6,"l":"thu-thach"},{"p":"Vitamin và chất khoáng có nhiều trong nhóm thực phẩm nào?","o":["Rau củ và trái cây tươi","Bánh kẹo ngọt","Nước ngọt có ga","Mỡ động vật"],"a":"Rau củ và trái cây tươi","h":"Nhóm này có màu sắc tươi sáng và thường ăn tươi hoặc nấu nhanh.","e":"Rau củ và trái cây tươi chứa nhiều vitamin và chất khoáng, cần thiết cho sức khỏe và sức đề kháng của cơ thể.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Thực phẩm để lâu, có mùi lạ và đổi màu thì em nên xử lí thế nào?","o":["Vẫn ăn bình thường cho khỏi lãng phí","Không nên sử dụng vì thực phẩm có thể đã bị hỏng, ăn vào không an toàn","Cho thật nhiều gia vị vào rồi ăn","Đem ra phơi nắng rồi ăn tiếp"],"a":"Không nên sử dụng vì thực phẩm có thể đã bị hỏng, ăn vào không an toàn","h":"Mùi lạ và đổi màu là dấu hiệu thực phẩm đã bị hỏng.","e":"Thực phẩm có mùi lạ, đổi màu là đã bị hỏng, có thể chứa vi khuẩn gây ngộ độc nên tuyệt đối không sử dụng.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Nồi cơm điện gồm các bộ phận chính nào?","o":["Chỉ gồm dây điện và phích cắm","Gồm quạt gió và bóng đèn","Gồm thân nồi, nồi nấu bên trong và bộ phận sinh nhiệt","Gồm bình chứa nước và ống dẫn"],"a":"Gồm thân nồi, nồi nấu bên trong và bộ phận sinh nhiệt","h":"Nồi cơm điện cần có phần chứa gạo và phần tạo ra nhiệt.","e":"Nồi cơm điện gồm thân nồi, nồi nấu (ruột nồi) bên trong và bộ phận sinh nhiệt (mâm nhiệt) giúp nấu chín cơm.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi sử dụng bếp điện, em cần chú ý điều gì để đảm bảo an toàn?","o":["Đặt bếp sát rèm cửa cho tiện nấu","Dùng tay ướt để cắm phích điện","Để khăn ướt phủ lên bếp khi đang nấu","Không để vật dễ cháy gần bếp và không dùng tay ướt chạm vào thiết bị điện"],"a":"Không để vật dễ cháy gần bếp và không dùng tay ướt chạm vào thiết bị điện","h":"Điện và nước, lửa là những yếu tố cần hết sức cẩn thận.","e":"Khi dùng bếp điện phải để xa vật dễ cháy, không dùng tay ướt chạm vào thiết bị và luôn chú ý khi nấu để phòng cháy nổ, điện giật.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Công dụng chính của nồi cơm điện là gì?","o":["Nấu cơm và giữ ấm cơm","Đun nước sôi để pha trà","Xay sinh tố hoa quả","Là (ủi) quần áo"],"a":"Nấu cơm và giữ ấm cơm","h":"Tên của đồ dùng đã nói lên công dụng chính của nó.","e":"Nồi cơm điện dùng để nấu cơm chín đều và có chế độ giữ ấm, giúp cơm luôn nóng khi đến bữa ăn.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi nồi cơm điện đang nấu, em không nên làm việc nào?","o":["Đậy kín nắp nồi","Mở nắp liên tục và đưa tay vào vùng hơi nước nóng thoát ra","Đặt nồi trên mặt bàn phẳng, khô ráo","Để nồi xa tầm với của em nhỏ"],"a":"Mở nắp liên tục và đưa tay vào vùng hơi nước nóng thoát ra","h":"Hơi nước nóng thoát ra khi nấu có thể làm bỏng da.","e":"Khi nồi đang nấu, hơi nước nóng thoát ra mạnh. Mở nắp liên tục vừa làm cơm lâu chín, vừa dễ bị bỏng do hơi nóng.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vì sao đèn LED được khuyến khích sử dụng trong gia đình thay cho đèn sợi đốt?","o":["Đèn LED sáng chói và toả nhiệt nhiều hơn đèn sợi đốt","Đèn LED rẻ hơn hẳn nhưng nhanh hỏng hơn đèn sợi đốt","Đèn LED tiết kiệm điện hơn và có tuổi thọ cao hơn đèn sợi đốt","Đèn LED không cần cắm điện vẫn sáng được"],"a":"Đèn LED tiết kiệm điện hơn và có tuổi thọ cao hơn đèn sợi đốt","h":"Đèn LED tiêu thụ ít điện năng mà vẫn cho độ sáng tốt.","e":"Đèn LED chuyển hoá phần lớn điện năng thành ánh sáng nên tiết kiệm điện, ít toả nhiệt và bền hơn đèn sợi đốt, giúp gia đình giảm chi phí tiền điện.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi sử dụng bếp hồng ngoại, việc làm nào sau đây là an toàn?","o":["Không chạm tay vào mặt bếp khi đang nấu và một lúc sau khi tắt, vì mặt bếp còn rất nóng","Đặt tay lên mặt bếp để kiểm tra bếp đã nóng chưa","Dùng nồi có đáy cong, lồi lõm để nấu cho nhanh sôi","Lấy khăn ướt lau mặt bếp ngay khi bếp đang nóng đỏ"],"a":"Không chạm tay vào mặt bếp khi đang nấu và một lúc sau khi tắt, vì mặt bếp còn rất nóng","h":"Mặt bếp hồng ngoại nóng đỏ khi nấu và còn nóng rất lâu sau khi tắt.","e":"Khi nấu, mặt bếp hồng ngoại nóng đỏ và truyền nhiệt trực tiếp. Em không được chạm tay vào mặt bếp, nên dùng nồi có đáy phẳng và chờ bếp nguội hẳn rồi mới vệ sinh.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây giúp gia đình em tiết kiệm điện và sử dụng điện an toàn?","o":["Bật đèn sáng cả ngày dù không có người trong phòng","Tắt đèn khi ra khỏi phòng và chọn thiết bị có nhãn năng lượng nhiều sao","Cắm càng nhiều thiết bị vào một ổ cắm càng tốt","Để ti vi ở chế độ chờ suốt ngày đêm"],"a":"Tắt đèn khi ra khỏi phòng và chọn thiết bị có nhãn năng lượng nhiều sao","h":"Nhãn năng lượng trên thiết bị cho biết mức tiết kiệm điện của thiết bị đó.","e":"Tắt đèn khi ra khỏi phòng, tắt thiết bị khi không sử dụng và ưu tiên thiết bị có nhãn năng lượng nhiều sao giúp gia đình tiết kiệm điện, giảm chi phí và an toàn hơn.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trồng trọt có vai trò nào sau đây đối với đời sống và sản xuất?","o":["Cung cấp lương thực, thực phẩm cho con người và nguyên liệu cho công nghiệp chế biến","Chỉ dùng để trang trí, làm cảnh trong gia đình","Chỉ cung cấp thức ăn cho vật nuôi trong chăn nuôi","Làm cạn kiệt nguồn nước và đất canh tác"],"a":"Cung cấp lương thực, thực phẩm cho con người và nguyên liệu cho công nghiệp chế biến","h":"Trồng trọt là ngành sản xuất chính của nông nghiệp.","e":"Trồng trọt cung cấp lương thực, thực phẩm cho con người, thức ăn cho chăn nuôi và nguyên liệu cho công nghiệp chế biến, hàng hoá xuất khẩu.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Giống cây trồng tốt cần có những đặc điểm nào sau đây?","o":["Chỉ cần cho quả to, màu sắc đẹp","Sinh trưởng tốt, năng suất cao, chất lượng tốt và chống chịu được sâu, bệnh","Chỉ cần mọc nhanh, không cần năng suất","Phải là giống mua từ nước ngoài về"],"a":"Sinh trưởng tốt, năng suất cao, chất lượng tốt và chống chịu được sâu, bệnh","h":"Hãy nghĩ đến mục đích cuối cùng khi chọn giống để gieo trồng.","e":"Giống tốt phải sinh trưởng, phát triển tốt trong điều kiện ngoại cảnh nhất định, cho năng suất cao, chất lượng tốt và chống chịu được sâu, bệnh hại.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Đất trồng gồm những thành phần chính nào?","o":["Chỉ gồm chất khoáng và chất hữu cơ","Phần rắn và phần lỏng, không có phần khí","Phần rắn, phần lỏng và phần khí","Chỉ gồm nước và không khí"],"a":"Phần rắn, phần lỏng và phần khí","h":"Đất trồng không chỉ là phần đất khô mà ta nhìn thấy.","e":"Đất trồng gồm ba thành phần: phần rắn (chất khoáng và chất hữu cơ), phần lỏng (nước trong đất) và phần khí (không khí trong đất).","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Gieo trồng đúng thời vụ mang lại lợi ích gì cho cây trồng?","o":["Cây không cần chăm sóc nữa","Tiết kiệm được toàn bộ phân bón","Cây cho thu hoạch quanh năm","Cây sinh trưởng, phát triển tốt, hạn chế được sâu, bệnh và thời tiết bất lợi"],"a":"Cây sinh trưởng, phát triển tốt, hạn chế được sâu, bệnh và thời tiết bất lợi","h":"Mỗi loại cây chỉ thích hợp gieo trồng vào một khoảng thời gian nhất định trong năm.","e":"Gieo trồng đúng thời vụ giúp cây trồng sinh trưởng, phát triển tốt, tránh được sâu, bệnh hại và các điều kiện thời tiết bất lợi, cho năng suất cao.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Nên tưới nước cho cây trồng vào thời điểm nào trong ngày là tốt nhất?","o":["Vào giữa trưa nắng gắt","Vào lúc trời đang mưa to","Vào bất kì lúc nào, không có sự khác biệt","Vào sáng sớm hoặc chiều mát"],"a":"Vào sáng sớm hoặc chiều mát","h":"Tưới nước lúc trời nắng gắt dễ làm cây bị sốc nhiệt và nước bốc hơi nhanh.","e":"Tưới nước vào sáng sớm hoặc chiều mát giúp cây hấp thụ nước tốt, tránh lãng phí nước do bốc hơi và hạn chế cây bị sốc nhiệt, cháy lá.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Bón phân hữu cơ cho đất trồng có tác dụng gì?","o":["Làm đất chai cứng và bạc màu nhanh","Tiêu diệt toàn bộ vi sinh vật trong đất","Làm đất tơi xốp, tăng độ phì nhiêu cho đất","Chỉ giúp lá cây xanh đẹp tạm thời"],"a":"Làm đất tơi xốp, tăng độ phì nhiêu cho đất","h":"Phân hữu cơ có nguồn gốc từ phân chuồng, phân xanh, rác thải hữu cơ hoai mục.","e":"Phân hữu cơ giúp cải tạo đất, làm đất tơi xốp, tăng độ phì nhiêu và cung cấp chất dinh dưỡng cho cây trồng một cách lâu dài.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Làm cỏ, vun xới cho cây trồng có tác dụng gì?","o":["Làm cho cây trồng nhanh bị héo úa","Diệt cỏ dại, làm đất tơi xốp, giúp bộ rễ phát triển và hạn chế nơi trú ẩn của sâu, bệnh","Chỉ nhằm làm cho luống cây trông đẹp hơn","Làm giảm mạnh độ ẩm của đất"],"a":"Diệt cỏ dại, làm đất tơi xốp, giúp bộ rễ phát triển và hạn chế nơi trú ẩn của sâu, bệnh","h":"Cỏ dại cạnh tranh nước và chất dinh dưỡng với cây trồng.","e":"Làm cỏ, vun xới giúp diệt cỏ dại, phá váng mặt đất, làm đất tơi xốp để rễ cây hô hấp và hút chất dinh dưỡng tốt, đồng thời hạn chế sâu, bệnh hại.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Biện pháp phòng trừ sâu, bệnh hại nào sau đây an toàn cho con người và thân thiện với môi trường?","o":["Sử dụng thiên địch, bẫy sinh học và giống cây chống chịu sâu, bệnh","Phun thuốc hoá học với liều lượng càng cao càng tốt","Phun thuốc hoá học ngay trước ngày thu hoạch","Trộn nhiều loại thuốc hoá học với nhau khi phun"],"a":"Sử dụng thiên địch, bẫy sinh học và giống cây chống chịu sâu, bệnh","h":"Hãy nghĩ đến biện pháp phòng trừ tổng hợp, ưu tiên biện pháp sinh học.","e":"Phòng trừ tổng hợp ưu tiên biện pháp canh tác, giống chống chịu và biện pháp sinh học (thiên địch, bẫy) để bảo vệ môi trường, an toàn cho người và sản phẩm.","t":"cn-lop7","g":7,"l":"thu-thach"},{"p":"Thu hoạch nông sản đúng thời điểm có tác dụng gì?","o":["Đảm bảo được số lượng và chất lượng của nông sản","Làm nông sản nhanh bị hư hỏng hơn","Làm giảm năng suất của cây trồng","Làm tăng chi phí bảo quản nông sản"],"a":"Đảm bảo được số lượng và chất lượng của nông sản","h":"Thu hoạch quá sớm hay quá muộn đều ảnh hưởng đến sản phẩm thu được.","e":"Thu hoạch đúng độ chín, đúng thời điểm giúp nông sản đạt số lượng và chất lượng cao nhất, tránh rơi rụng, hư hỏng, giảm tổn thất sau thu hoạch.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Sau khi thu hoạch, thóc cần được bảo quản như thế nào để không bị ẩm mốc, mối mọt?","o":["Đổ thành đống ngay khi thóc còn ướt","Để ngoài sân nhiều ngày cho tự khô","Phơi hoặc sấy khô rồi cất giữ ở nơi khô ráo, thoáng mát","Trộn lẫn thóc với phân bón để chống mọt"],"a":"Phơi hoặc sấy khô rồi cất giữ ở nơi khô ráo, thoáng mát","h":"Độ ẩm cao là điều kiện để nấm mốc và mối mọt phát triển.","e":"Thóc sau thu hoạch phải được phơi hoặc sấy khô đến độ ẩm an toàn, làm sạch rồi bảo quản ở nơi khô ráo, thoáng mát để tránh ẩm mốc và mối mọt.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Khi chọn giống vật nuôi, nên chọn những con giống có đặc điểm nào?","o":["Con nào có giá rẻ nhất thì chọn","Khoẻ mạnh, nguồn gốc rõ ràng, phù hợp với mục đích chăn nuôi","Chỉ cần to con, không cần khoẻ mạnh","Chọn con đang ốm yếu để được giảm giá"],"a":"Khoẻ mạnh, nguồn gốc rõ ràng, phù hợp với mục đích chăn nuôi","h":"Giống tốt là yếu tố quan trọng quyết định năng suất chăn nuôi.","e":"Vật nuôi giống phải khoẻ mạnh, không bệnh tật, có nguồn gốc rõ ràng và phù hợp với mục đích nuôi (lấy thịt, lấy trứng, lấy sữa...) thì mới cho năng suất cao.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Thức ăn cho gà cần đảm bảo yêu cầu nào sau đây?","o":["Chỉ cần cho ăn thóc là đủ","Càng trộn nhiều muối càng tốt","Cho ăn thức ăn đã ôi thiu để tiết kiệm","Đủ năng lượng, protein, chất khoáng và vitamin"],"a":"Đủ năng lượng, protein, chất khoáng và vitamin","h":"Gà ở mỗi giai đoạn sinh trưởng cần khẩu phần ăn cân đối các chất dinh dưỡng.","e":"Thức ăn cho gà phải đảm bảo đủ và cân đối năng lượng, protein, chất khoáng và vitamin thì gà mới sinh trưởng, phát triển tốt và cho năng suất cao.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Chuồng nuôi vật nuôi cần được vệ sinh như thế nào?","o":["Chỉ dọn dẹp khi chuồng đã có mùi hôi nặng","Thường xuyên quét dọn, khử trùng, giữ chuồng luôn khô ráo, sạch sẽ","Không cần dọn phân, chỉ cần cho ăn đầy đủ","Giữ chuồng luôn ẩm ướt để vật nuôi mát"],"a":"Thường xuyên quét dọn, khử trùng, giữ chuồng luôn khô ráo, sạch sẽ","h":"Chuồng bẩn là nơi mầm bệnh dễ phát sinh và lây lan.","e":"Vệ sinh chuồng trại thường xuyên (quét dọn, rửa, khử trùng, giữ khô ráo) giúp vật nuôi khoẻ mạnh, hạn chế mầm bệnh và ô nhiễm môi trường.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Biện pháp nào sau đây giúp phòng bệnh hiệu quả cho vật nuôi?","o":["Chỉ chữa trị khi vật nuôi đã mắc bệnh nặng","Cho vật nuôi uống thuốc chữa bệnh của người","Cách li những con vật nuôi khoẻ mạnh khỏi đàn","Tiêm phòng vắc-xin đầy đủ và đúng lịch cho vật nuôi"],"a":"Tiêm phòng vắc-xin đầy đủ và đúng lịch cho vật nuôi","h":"Phòng bệnh luôn tốt hơn và rẻ hơn chữa bệnh.","e":"Tiêm phòng vắc-xin đầy đủ, đúng lịch kết hợp vệ sinh chuồng trại và chăm sóc tốt là biện pháp phòng bệnh chủ động, hiệu quả nhất cho vật nuôi.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Chuồng nuôi lợn cần đảm bảo điều kiện nào sau đây?","o":["Thông thoáng, ấm về mùa đông, mát về mùa hè, tránh gió lùa và mưa hắt","Kín mít, không cần cửa thông gió","Luôn ẩm ướt, nền chuồng đầy bùn","Càng chật hẹp càng tốt để lợn ít vận động"],"a":"Thông thoáng, ấm về mùa đông, mát về mùa hè, tránh gió lùa và mưa hắt","h":"Môi trường chuồng nuôi ảnh hưởng trực tiếp đến sức khoẻ của lợn.","e":"Chuồng nuôi lợn phải cao ráo, thông thoáng, tránh gió lùa, mưa hắt; ấm về mùa đông, mát về mùa hè thì lợn mới khoẻ mạnh, ít bệnh và lớn nhanh.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Để bảo vệ môi trường trong chăn nuôi, chất thải của vật nuôi nên được xử lí bằng cách nào?","o":["Xả thẳng ra sông, suối gần nhà","Đổ ra đường đi chung của xóm","Ủ làm phân bón hữu cơ hoặc đưa vào hầm biogas","Để nguyên trong chuồng, không cần xử lí"],"a":"Ủ làm phân bón hữu cơ hoặc đưa vào hầm biogas","h":"Chất thải chăn nuôi nếu xử lí đúng cách sẽ thành nguồn phân bón và chất đốt có ích.","e":"Ủ chất thải làm phân hữu cơ hoặc xử lí bằng hầm biogas vừa giảm ô nhiễm môi trường, vừa tạo phân bón cho cây trồng và khí đốt phục vụ sinh hoạt.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Nhóm thức ăn nào sau đây giàu protein, thích hợp bổ sung cho vật nuôi?","o":["Rơm rạ, cỏ khô","Ngô, sắn, khoai lang","Đậu tương, bột cá, bột thịt","Muối khoáng và nước uống"],"a":"Đậu tương, bột cá, bột thịt","h":"Protein là chất dinh dưỡng giúp vật nuôi tạo thịt, trứng, sữa.","e":"Các thức ăn như đậu tương, bột cá, bột thịt, khô dầu chứa nhiều protein; trong khi ngô, sắn chủ yếu cung cấp năng lượng, rơm rạ nhiều chất xơ.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Máng ăn và máng uống cho vật nuôi cần được chăm sóc như thế nào?","o":["Rửa sạch thường xuyên, nước uống luôn sạch và đầy đủ","Để thức ăn thừa đọng lại nhiều ngày","Không cần rửa, chỉ cần thêm thức ăn mới lên trên","Dùng chung máng cho cả vật nuôi bệnh và khoẻ mà không khử trùng"],"a":"Rửa sạch thường xuyên, nước uống luôn sạch và đầy đủ","h":"Thức ăn, nước uống bẩn là đường lây bệnh cho vật nuôi.","e":"Máng ăn, máng uống phải được rửa sạch thường xuyên; thức ăn thừa phải dọn bỏ, nước uống luôn sạch thì vật nuôi mới ăn uống tốt và ít mắc bệnh đường tiêu hoá.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Trước khi thả cá giống, ao nuôi cần được xử lí như thế nào?","o":["Thả cá ngay vào ao cũ, không cần xử lí","Đổ thật nhiều phân tươi xuống ao","Để ao đầy cỏ dại, rác và cá tạp","Tát cạn, vét bùn, bón vôi khử trùng, phơi đáy ao rồi mới lấy nước sạch vào"],"a":"Tát cạn, vét bùn, bón vôi khử trùng, phơi đáy ao rồi mới lấy nước sạch vào","h":"Ao nuôi chưa xử lí còn chứa mầm bệnh và địch hại của cá.","e":"Chuẩn bị ao nuôi gồm: tát cạn, vét bớt bùn đáy, bón vôi khử trùng, phơi đáy ao, diệt cá tạp, địch hại rồi mới cấp nước sạch vào ao để thả cá giống.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Khi cho cá ăn, cần đảm bảo nguyên tắc nào sau đây?","o":["Cho ăn càng nhiều càng tốt để cá mau lớn","Đúng lượng, đúng giờ, đúng vị trí và thức ăn đảm bảo chất lượng","Cho ăn vào giữa trưa nắng gắt","Thay đổi giờ cho ăn liên tục mỗi ngày"],"a":"Đúng lượng, đúng giờ, đúng vị trí và thức ăn đảm bảo chất lượng","h":"Cho ăn thừa sẽ làm ô nhiễm nước ao và lãng phí thức ăn.","e":"Cho cá ăn đúng lượng, đúng giờ, đúng vị trí cố định giúp cá ăn hết thức ăn, lớn đều, đồng thời tránh thừa thức ăn gây ô nhiễm nước ao.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Nước ao nuôi cá được coi là tốt khi có màu nào sau đây?","o":["Màu đen, có mùi hôi thối","Màu xanh nõn chuối","Màu đỏ gạch, nổi váng dày","Trong veo hoàn toàn như nước uống"],"a":"Màu xanh nõn chuối","h":"Màu nước ao thể hiện sự phát triển của các sinh vật phù du làm thức ăn tự nhiên cho cá.","e":"Nước ao có màu xanh nõn chuối chứng tỏ tảo lục và sinh vật phù du phát triển thích hợp, tạo nguồn thức ăn tự nhiên và ôxi cho cá; nước đen, đỏ gạch là dấu hiệu nước bị ô nhiễm.","t":"cn-lop7","g":7,"l":"thu-thach"},{"p":"Thả cá với mật độ quá dày sẽ gây ra hậu quả gì?","o":["Cá lớn nhanh hơn bình thường","Tiết kiệm được nhiều thức ăn","Cá chậm lớn, thiếu ôxi và dễ phát sinh dịch bệnh","Nước ao luôn trong và sạch hơn"],"a":"Cá chậm lớn, thiếu ôxi và dễ phát sinh dịch bệnh","h":"Ao nuôi chỉ nuôi được một lượng cá nhất định phù hợp với diện tích và độ sâu của ao.","e":"Mật độ thả quá dày làm cá cạnh tranh thức ăn và ôxi, chất thải nhiều khiến nước ao ô nhiễm, cá chậm lớn và dễ bùng phát dịch bệnh.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Người ta thường áp dụng những phương pháp nào để chọn tạo giống cây trồng mới?","o":["Chỉ bón thật nhiều phân cho cây","Chọn lọc và lai","Trồng cây ở càng nhiều nơi càng tốt","Thu hoạch sớm hơn bình thường"],"a":"Chọn lọc và lai","h":"Các nhà chọn giống thường kết hợp những cây bố, mẹ có đặc tính tốt với nhau.","e":"Chọn tạo giống cây trồng thường dùng phương pháp chọn lọc (chọn cây tốt làm giống) và lai (lai hai giống khác nhau) để tạo giống mới có năng suất cao, chất lượng tốt và chống chịu được sâu, bệnh.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Bản vẽ kĩ thuật là tài liệu dùng để làm gì?","o":["Trang trí cho sản phẩm thêm đẹp","Quảng cáo sản phẩm tới người mua","Trình bày hình dạng, kích thước và yêu cầu kĩ thuật của sản phẩm để chế tạo và kiểm tra sản phẩm","Ghi lại địa chỉ của nhà máy sản xuất"],"a":"Trình bày hình dạng, kích thước và yêu cầu kĩ thuật của sản phẩm để chế tạo và kiểm tra sản phẩm","h":"Bản vẽ kĩ thuật được coi là ngôn ngữ chung trong kĩ thuật.","e":"Bản vẽ kĩ thuật trình bày đầy đủ hình dạng, kích thước và các yêu cầu kĩ thuật của sản phẩm theo quy tắc thống nhất, làm căn cứ để chế tạo và kiểm tra sản phẩm.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong phép chiếu vuông góc, các tia chiếu có đặc điểm gì?","o":["Song song với nhau và vuông góc với mặt phẳng hình chiếu","Hội tụ tại một điểm ở phía trước vật thể","Chiếu xiên góc tuỳ ý lên mặt phẳng hình chiếu","Luôn vuông góc với vật thể được chiếu"],"a":"Song song với nhau và vuông góc với mặt phẳng hình chiếu","h":"Tên gọi của phép chiếu gợi ý hướng của tia chiếu so với mặt phẳng hình chiếu.","e":"Phép chiếu vuông góc dùng các tia chiếu song song với nhau và vuông góc với mặt phẳng hình chiếu, cho hình chiếu đúng hình dạng, kích thước thật theo các chiều của vật thể.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Hình chiếu đứng của vật thể cho biết những kích thước nào?","o":["Chiều dài và chiều rộng của vật thể","Chiều rộng và chiều cao của vật thể","Chỉ cho biết chiều cao của vật thể","Chiều dài và chiều cao của vật thể"],"a":"Chiều dài và chiều cao của vật thể","h":"Hình chiếu đứng là hình chiếu nhìn từ phía trước của vật thể.","e":"Hình chiếu đứng (nhìn từ phía trước) thể hiện chiều dài và chiều cao của vật thể.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Hình chiếu bằng của vật thể cho biết những kích thước nào?","o":["Chiều dài và chiều cao của vật thể","Chiều dài và chiều rộng của vật thể","Chiều rộng và chiều cao của vật thể","Chỉ cho biết chiều rộng của vật thể"],"a":"Chiều dài và chiều rộng của vật thể","h":"Hình chiếu bằng là hình chiếu nhìn từ phía trên xuống.","e":"Hình chiếu bằng (nhìn từ trên xuống) thể hiện chiều dài và chiều rộng của vật thể.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Hình chiếu cạnh của vật thể cho biết những kích thước nào?","o":["Chiều dài và chiều cao của vật thể","Chiều rộng và chiều cao của vật thể","Chiều dài và chiều rộng của vật thể","Chỉ cho biết chiều cao của vật thể"],"a":"Chiều rộng và chiều cao của vật thể","h":"Hình chiếu cạnh là hình chiếu nhìn từ phía bên (trái) của vật thể.","e":"Hình chiếu cạnh (nhìn từ phía bên) thể hiện chiều rộng và chiều cao của vật thể.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Theo cách bố trí hình chiếu theo tiêu chuẩn Việt Nam, hình chiếu bằng được đặt ở vị trí nào so với hình chiếu đứng?","o":["Ở phía trên hình chiếu đứng","Ở phía bên phải hình chiếu đứng","Đặt tách rời, không liên quan vị trí với hình chiếu đứng","Ở phía dưới hình chiếu đứng"],"a":"Ở phía dưới hình chiếu đứng","h":"Vị trí các hình chiếu trên bản vẽ phải tuân theo quy tắc thống nhất để người đọc dễ đối chiếu.","e":"Theo phương pháp chiếu góc thứ nhất áp dụng ở Việt Nam: hình chiếu bằng đặt dưới hình chiếu đứng, hình chiếu cạnh đặt bên phải hình chiếu đứng.","t":"cn-lop8","g":8,"l":"thu-thach"},{"p":"Trên bản vẽ kĩ thuật, nét liền đậm được dùng để vẽ loại đường nào?","o":["Đường bao thấy của vật thể","Đường bao khuất của vật thể","Đường tâm và đường trục","Đường kích thước và đường gióng"],"a":"Đường bao thấy của vật thể","h":"Mỗi loại đường nét trên bản vẽ có quy định sử dụng riêng.","e":"Nét liền đậm dùng để vẽ đường bao thấy của vật thể; đường bao khuất vẽ bằng nét đứt, đường tâm và đường trục vẽ bằng nét gạch dài – chấm – mảnh.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Nhóm vật liệu nào sau đây đều là vật liệu kim loại?","o":["Cao su, nhựa, đồng","Nhôm, gỗ, thuỷ tinh","Đồng, nhôm, thép","Thép, gốm, cao su"],"a":"Đồng, nhôm, thép","h":"Kim loại có tính dẫn điện, dẫn nhiệt và có ánh kim.","e":"Đồng, nhôm, thép đều là kim loại; cao su, nhựa, gỗ, thuỷ tinh, gốm là vật liệu phi kim loại.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Vật liệu nào sau đây là vật liệu phi kim loại?","o":["Gang","Đồng","Nhôm","Cao su"],"a":"Cao su","h":"Vật liệu phi kim loại thường không dẫn điện, cách nhiệt tốt.","e":"Cao su là vật liệu phi kim loại; gang, đồng, nhôm đều là kim loại (gang, đồng và nhôm là các kim loại/hợp kim thông dụng).","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Để đo kích thước của chi tiết cơ khí với độ chính xác cao, người ta thường dùng dụng cụ nào?","o":["Thước dây bằng vải","Thước cặp (thước kẹp)","Thước gỗ của học sinh","Ước lượng bằng mắt thường"],"a":"Thước cặp (thước kẹp)","h":"Thước cặp có du xích giúp đọc kích thước chính xác đến phần nhỏ của milimét.","e":"Thước cặp (thước kẹp) dùng để đo kích thước ngoài, kích thước trong và chiều sâu của chi tiết với độ chính xác cao, thường đạt 0,1 mm; 0,05 mm hoặc 0,02 mm.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khi cưa và dũa kim loại, cần làm gì để đảm bảo an toàn?","o":["Dùng một tay giữ vật, một tay cầm cưa","Thổi mạnh cho phoi bay khỏi mặt bàn","Kẹp chặt vật gia công trên ê-tô và không dùng tay gạt phoi","Đứng càng sát lưỡi cưa càng tốt để nhìn rõ"],"a":"Kẹp chặt vật gia công trên ê-tô và không dùng tay gạt phoi","h":"Phoi kim loại sắc, dễ gây đứt tay và bắn vào mắt.","e":"Khi cưa, dũa phải kẹp chặt vật trên ê-tô, đeo kính bảo hộ; dùng bàn chải quét phoi, tuyệt đối không dùng tay gạt hoặc thổi phoi vì phoi sắc dễ gây thương tích.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khi làm việc trong phân xưởng cơ khí, người lao động cần thực hiện điều nào sau đây?","o":["Mặc quần áo gọn gàng, đeo kính bảo hộ và tuân thủ nội quy an toàn lao động","Để tóc dài xoã tự do khi đứng gần máy đang chạy","Đùa nghịch, chạy nhảy trong phân xưởng","Đi dép lê để dễ di chuyển trong xưởng"],"a":"Mặc quần áo gọn gàng, đeo kính bảo hộ và tuân thủ nội quy an toàn lao động","h":"An toàn lao động là yêu cầu bắt buộc trong sản xuất cơ khí.","e":"Người lao động phải mặc trang phục gọn gàng, sử dụng đầy đủ dụng cụ bảo hộ (kính, găng tay phù hợp...) và tuân thủ nội quy an toàn để tránh tai nạn lao động.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Truyền động đai truyền được chuyển động là nhờ vào đâu?","o":["Lực ma sát giữa dây đai và bánh đai","Các răng của hai bánh ăn khớp với nhau","Lực hút của nam châm giữa hai bánh","Áp lực của dầu bôi trơn"],"a":"Lực ma sát giữa dây đai và bánh đai","h":"Dây đai ôm sát và ép lên bề mặt bánh đai khi làm việc.","e":"Trong truyền động đai, chuyển động được truyền nhờ lực ma sát giữa dây đai và bánh đai; bánh dẫn quay kéo dây đai chuyển động làm bánh bị dẫn quay theo.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong truyền động bánh răng, chuyển động được truyền đi bằng cách nào?","o":["Một dây đai nối hai bánh răng lại","Hai mặt bánh nhẵn ép chặt vào nhau","Các răng của hai bánh răng ăn khớp trực tiếp với nhau","Một sợi xích nối hai bánh răng"],"a":"Các răng của hai bánh răng ăn khớp trực tiếp với nhau","h":"Truyền động bánh răng thường dùng khi cần tỉ số truyền chính xác.","e":"Truyền động bánh răng truyền chuyển động nhờ các răng của bánh dẫn và bánh bị dẫn ăn khớp với nhau, cho tỉ số truyền chính xác, không bị trượt.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Cơ cấu tay quay – con trượt có tác dụng biến đổi chuyển động như thế nào?","o":["Biến chuyển động tịnh tiến thành chuyển động quay","Biến chuyển động quay thành chuyển động tịnh tiến qua lại","Biến chuyển động quay chậm thành chuyển động quay nhanh hơn","Giữ nguyên chuyển động quay, không biến đổi"],"a":"Biến chuyển động quay thành chuyển động tịnh tiến qua lại","h":"Cơ cấu này có trong động cơ đốt trong và máy nén khí.","e":"Cơ cấu tay quay – con trượt biến chuyển động quay của tay quay thành chuyển động tịnh tiến qua lại của con trượt (ứng dụng trong máy khâu đạp chân, động cơ...).","t":"cn-lop8","g":8,"l":"thu-thach"},{"p":"Một mạch điện trong gia đình cơ bản gồm những thành phần chính nào?","o":["Chỉ gồm bóng đèn và dây dẫn","Chỉ gồm nguồn điện và công tắc","Gồm pin, chuông và đèn pin","Nguồn điện, dây dẫn, thiết bị đóng – cắt và bảo vệ, thiết bị tiêu thụ điện"],"a":"Nguồn điện, dây dẫn, thiết bị đóng – cắt và bảo vệ, thiết bị tiêu thụ điện","h":"Mạch điện phải là một vòng kín gồm đủ các phần tử cơ bản.","e":"Mạch điện gồm: nguồn điện, dây dẫn, thiết bị đóng – cắt (công tắc, cầu dao), thiết bị bảo vệ (cầu chì, át-tô-mát) và thiết bị tiêu thụ điện (phụ tải).","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Cầu chì có tác dụng gì trong mạch điện gia đình?","o":["Làm tăng điện áp cho các thiết bị điện","Giúp tiết kiệm điện năng tiêu thụ","Tự động ngắt mạch điện khi xảy ra ngắn mạch hoặc quá tải để bảo vệ mạch điện","Thay thế hoàn toàn cho công tắc điện"],"a":"Tự động ngắt mạch điện khi xảy ra ngắn mạch hoặc quá tải để bảo vệ mạch điện","h":"Cầu chì là thiết bị bảo vệ, không phải thiết bị đóng – cắt thông thường.","e":"Khi dòng điện tăng quá mức cho phép (ngắn mạch, quá tải), dây chì trong cầu chì nóng chảy và đứt, tự động ngắt mạch, bảo vệ dây dẫn và thiết bị điện khỏi cháy hỏng.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khi dòng điện trong mạch vượt quá giá trị cho phép, cầu chì bảo vệ mạch điện bằng cách nào?","o":["Dây chì phát sáng để báo hiệu cho người dùng","Dây chì giãn dài ra làm hở tiếp điểm","Vỏ cầu chì tự vỡ để thoát nhiệt","Dây chì bị dòng điện lớn làm nóng chảy và đứt, ngắt mạch điện"],"a":"Dây chì bị dòng điện lớn làm nóng chảy và đứt, ngắt mạch điện","h":"Dây chì làm bằng kim loại dễ nóng chảy, mắc nối tiếp trong mạch điện.","e":"Dây chì có nhiệt độ nóng chảy thấp; khi dòng điện vượt quá định mức, dây chì nóng chảy và đứt ra, ngắt mạch điện, bảo vệ toàn bộ mạch phía sau cầu chì.","t":"cn-lop8","g":8,"l":"thu-thach"},{"p":"Át-tô-mát (cầu dao tự động) khác cầu chì ở điểm nào sau đây?","o":["Sau khi tự ngắt do sự cố, có thể đóng lại để sử dụng tiếp mà không phải thay thế bộ phận","Không có khả năng ngắt mạch khi quá tải","Chỉ sử dụng được cho mạch điện một chiều","Không có tác dụng bảo vệ mạch điện"],"a":"Sau khi tự ngắt do sự cố, có thể đóng lại để sử dụng tiếp mà không phải thay thế bộ phận","h":"Hãy liên hệ với cầu dao tự động thường lắp ở đầu nguồn điện trong nhà.","e":"Át-tô-mát tự động ngắt mạch khi quá tải hoặc ngắn mạch; sau khi khắc phục sự cố chỉ cần gạt cần đóng lại là dùng tiếp, tiện lợi hơn cầu chì phải thay dây chì mới.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây KHÔNG an toàn khi sử dụng điện?","o":["Rút phích cắm khi không sử dụng thiết bị điện","Dùng tay còn ướt để cắm phích điện vào ổ cắm","Kiểm tra và thay dây điện đã bị hở lõi","Ngắt cầu dao trước khi sửa chữa thiết bị điện"],"a":"Dùng tay còn ướt để cắm phích điện vào ổ cắm","h":"Nước là chất dẫn điện, tay ướt làm điện trở của cơ thể giảm mạnh.","e":"Tay ướt khi tiếp xúc với thiết bị điện rất dễ gây điện giật nguy hiểm; các việc còn lại đều là thói quen sử dụng điện an toàn.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Các thiết bị điện có vỏ bằng kim loại như tủ lạnh, máy giặt cần được nối đất nhằm mục đích gì?","o":["Giúp thiết bị tiêu thụ ít điện năng hơn","Tránh cho người sử dụng bị điện giật khi thiết bị bị rò điện ra vỏ","Làm cho thiết bị hoạt động mạnh hơn","Kéo dài tuổi thọ của động cơ thiết bị"],"a":"Tránh cho người sử dụng bị điện giật khi thiết bị bị rò điện ra vỏ","h":"Khi thiết bị rò điện, dòng điện rò cần có đường thoát xuống đất thay vì qua cơ thể người.","e":"Nối đất giúp dòng điện rò từ vỏ kim loại truyền xuống đất, bảo vệ người sử dụng không bị điện giật khi chạm vào thiết bị bị rò điện.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khi phát hiện dây điện bị đứt và rơi xuống đất, em cần làm gì?","o":["Đứng tránh xa, không chạm vào dây và báo ngay cho người lớn hoặc đơn vị điện lực","Cầm lấy dây để nối lại ngay","Dùng cây gậy còn ướt đẩy dây sang một bên","Đổ nước lên đoạn dây cho an toàn"],"a":"Đứng tránh xa, không chạm vào dây và báo ngay cho người lớn hoặc đơn vị điện lực","h":"Dây điện đứt rơi xuống đất vẫn có thể đang mang điện, cực kì nguy hiểm.","e":"Dây điện đứt có thể vẫn còn điện; phải đứng xa, cảnh báo mọi người không lại gần và báo ngay cho người lớn hoặc cơ quan điện lực đến xử lí.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Áptômát (cầu dao tự động) trong mạng điện gia đình có chức năng chính là gì?","o":["Đóng và cắt mạch điện bằng tay khi cần dùng điện","Tự động ngắt mạch khi có sự cố quá tải hoặc ngắn mạch","Tăng điện áp cho các thiết bị điện trong nhà","Đo lượng điện năng tiêu thụ của gia đình"],"a":"Tự động ngắt mạch khi có sự cố quá tải hoặc ngắn mạch","h":"Đây là thiết bị bảo vệ, hoạt động không cần con người tác động.","e":"Áptômát vừa đóng vai trò thiết bị đóng cắt, vừa tự động ngắt mạch khi dòng điện vượt quá mức cho phép hoặc xảy ra ngắn mạch, giúp bảo vệ mạng điện và thiết bị.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Dây dẫn điện trong nhà thường được làm bằng đồng vì lí do nào sau đây?","o":["Đồng dẫn điện tốt và tương đối bền","Đồng là kim loại nhẹ nhất","Đồng không bao giờ bị oxi hoá","Đồng rẻ hơn mọi kim loại khác"],"a":"Đồng dẫn điện tốt và tương đối bền","h":"Hãy nhớ tính chất vật lí quan trọng nhất của vật liệu làm dây dẫn.","e":"Đồng có điện trở suất nhỏ, dẫn điện tốt, độ bền cơ học khá cao nên được dùng phổ biến làm lõi dây dẫn điện.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi cần sửa chữa hoặc thay thế một thiết bị điện trong nhà, việc đầu tiên phải làm để đảm bảo an toàn là gì?","o":["Dùng bút thử điện kiểm tra vỏ thiết bị","Đeo găng tay cao su rồi thao tác ngay","Ngắt nguồn điện bằng áptômát hoặc cầu dao tổng","Rút hết phích cắm của các thiết bị khác trong nhà"],"a":"Ngắt nguồn điện bằng áptômát hoặc cầu dao tổng","h":"Nguyên tắc an toàn điện đầu tiên: cắt nguồn trước khi chạm vào mạch điện.","e":"Trước khi sửa chữa, lắp đặt thiết bị điện phải ngắt nguồn điện ở cầu dao/áptômát tổng và kiểm tra lại bằng bút thử điện để tránh bị điện giật.","t":"cn-lop9","g":9,"l":"thu-thach"},{"p":"Sơ đồ lắp đặt mạng điện trong nhà thể hiện nội dung gì?","o":["Màu sắc và kiểu dáng của các thiết bị điện","Giá thành của toàn bộ mạng điện","Cách trang trí dây điện cho đẹp nhà","Vị trí lắp đặt và cách nối dây giữa các phần tử của mạng điện"],"a":"Vị trí lắp đặt và cách nối dây giữa các phần tử của mạng điện","h":"Sơ đồ này là bản vẽ kĩ thuật dùng để thi công lắp đặt.","e":"Sơ đồ lắp đặt biểu diễn vị trí thực tế của các thiết bị (cầu dao, công tắc, ổ cắm, bóng đèn...) và đường đi của dây dẫn để thợ điện thi công đúng thiết kế.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Cầu chì trong mạch điện có tác dụng gì?","o":["Bảo vệ mạch điện, dây chì tự chảy và ngắt mạch khi dòng điện tăng quá mức","Làm cho bóng đèn sáng hơn bình thường","Biến đổi dòng điện xoay chiều thành một chiều","Đo cường độ dòng điện trong mạch"],"a":"Bảo vệ mạch điện, dây chì tự chảy và ngắt mạch khi dòng điện tăng quá mức","h":"Khi quá tải, bộ phận nào trong cầu chì sẽ bị nóng chảy trước?","e":"Dây chì trong cầu chì có nhiệt độ nóng chảy thấp; khi dòng điện vượt quá giá trị cho phép, dây chì nóng chảy và cắt mạch, bảo vệ các thiết bị phía sau.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây KHÔNG an toàn khi sử dụng điện trong gia đình?","o":["Không cắm chung quá nhiều thiết bị vào một ổ cắm","Dùng tay ướt để bật công tắc và cắm phích điện","Thay bóng đèn khi đã ngắt điện","Để dây điện tránh xa nguồn nhiệt cao"],"a":"Dùng tay ướt để bật công tắc và cắm phích điện","h":"Nước làm tăng khả năng dẫn điện của cơ thể người.","e":"Tay ướt làm điện trở của da giảm mạnh, dòng điện dễ truyền qua cơ thể gây điện giật nguy hiểm, vì vậy tuyệt đối không thao tác với thiết bị điện khi tay ướt.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Các thiết bị điện có vỏ bằng kim loại (như tủ lạnh, máy giặt) thường được nối đất nhằm mục đích gì?","o":["Giúp thiết bị chạy êm và nhanh hơn","Tiết kiệm điện năng khi vận hành","Tăng tuổi thọ của động cơ điện","Đưa dòng điện rò rỉ xuống đất, tránh nguy hiểm cho người sử dụng"],"a":"Đưa dòng điện rò rỉ xuống đất, tránh nguy hiểm cho người sử dụng","h":"Hãy nghĩ đến trường hợp vỏ kim loại bị rò điện.","e":"Khi có sự cố rò điện ra vỏ kim loại, dây nối đất dẫn dòng điện xuống đất thay vì truyền qua cơ thể người chạm vào, giúp tránh bị điện giật.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi chọn giống cây ăn quả để trồng, yêu cầu quan trọng nhất là gì?","o":["Giống cây phải là giống đắt tiền nhất","Giống cây phải có quả to nhất thị trường","Giống cây phải phù hợp với điều kiện khí hậu, đất đai của địa phương","Giống cây phải là giống mới nhập từ nước ngoài"],"a":"Giống cây phải phù hợp với điều kiện khí hậu, đất đai của địa phương","h":"Cây chỉ sinh trưởng tốt khi điều kiện ngoại cảnh thích hợp với đặc tính của giống.","e":"Mỗi giống cây ăn quả thích nghi với một điều kiện khí hậu, đất đai nhất định; chọn giống phù hợp địa phương giúp cây sinh trưởng tốt, ít sâu bệnh và cho năng suất cao.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi trồng cây ăn quả, người ta thường bón phân hữu cơ hoai mục xuống hố trước khi đặt cây (bón lót) nhằm mục đích gì?","o":["Cung cấp chất dinh dưỡng cho cây trong giai đoạn đầu sau khi trồng","Làm cho hố trồng sâu hơn","Xua đuổi sâu bọ trong đất","Giữ cho bầu đất không bị vỡ"],"a":"Cung cấp chất dinh dưỡng cho cây trong giai đoạn đầu sau khi trồng","h":"Phân hữu cơ phân huỷ chậm nên cần được chôn sẵn dưới hố.","e":"Bón lót bằng phân hữu cơ hoai mục trộn với đất ở đáy hố giúp cung cấp dinh dưỡng từ từ cho bộ rễ mới phát triển, giúp cây bén rễ và hồi xanh nhanh.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Đối với cây ăn quả, bón phân thúc thường được thực hiện vào những thời điểm nào?","o":["Chỉ bón một lần duy nhất khi mới trồng","Bón vào lúc cây đang bị sâu bệnh nặng","Bón trước khi cây ra hoa và trong giai đoạn nuôi quả","Bón ngay trước ngày thu hoạch một hôm"],"a":"Bón trước khi cây ra hoa và trong giai đoạn nuôi quả","h":"Hãy nhớ những giai đoạn cây cần nhiều dinh dưỡng nhất.","e":"Bón thúc trước khi ra hoa giúp cây phân hoá mầm hoa tốt; bón trong giai đoạn nuôi quả giúp quả lớn đều, chất lượng cao. Ngoài ra còn bón sau thu hoạch để cây phục hồi.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Cây ăn quả cần được tưới nước đầy đủ nhất vào giai đoạn nào?","o":["Giai đoạn cây ngủ nghỉ sau thu hoạch","Giai đoạn cây ra hoa, đậu quả và quả đang lớn","Giai đoạn chuẩn bị tỉa cành mùa đông","Bất kì lúc nào cây rụng lá"],"a":"Giai đoạn cây ra hoa, đậu quả và quả đang lớn","h":"Đây là lúc cây hút nhiều nước để nuôi bộ phận sinh sản.","e":"Thời kì ra hoa, đậu quả và quả lớn là lúc cây cần nhiều nước nhất; thiếu nước ở giai đoạn này dễ gây rụng hoa, rụng quả non và quả kém chất lượng.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi phun thuốc bảo vệ thực vật cho cây ăn quả sắp thu hoạch, điều quan trọng nhất phải tuân thủ là gì?","o":["Phun thuốc vào giữa trưa nắng gắt","Phun liều cao hơn hướng dẫn để trừ sâu triệt để","Phun thuốc ngay trước khi hái quả một ngày","Đảm bảo đúng thời gian cách li của thuốc trước khi thu hoạch"],"a":"Đảm bảo đúng thời gian cách li của thuốc trước khi thu hoạch","h":"Thuốc cần có đủ thời gian phân huỷ hết dư lượng trên quả.","e":"Mỗi loại thuốc bảo vệ thực vật đều có thời gian cách li quy định; phải ngừng phun trước khi thu hoạch đủ số ngày đó để dư lượng thuốc phân huỷ, đảm bảo an toàn cho người ăn.","t":"cn-lop9","g":9,"l":"thu-thach"},{"p":"Phương pháp chế biến món ăn nào sau đây có sử dụng nhiệt?","o":["Muối chua dưa cải","Hấp bánh cuốn","Trộn gỏi (nộm) rau củ","Ướp muối cá để bảo quản"],"a":"Hấp bánh cuốn","h":"Hãy tìm phương pháp làm chín thực phẩm bằng hơi nóng.","e":"Hấp là phương pháp chế biến có sử dụng nhiệt (nhiệt của hơi nước làm chín thực phẩm). Muối chua, trộn gỏi, ướp muối là các phương pháp không dùng nhiệt.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Bảo quản thực phẩm trong tủ lạnh giúp thực phẩm lâu hỏng chủ yếu vì lí do nào?","o":["Nhiệt độ thấp làm chậm sự phát triển của vi sinh vật gây hỏng thực phẩm","Tủ lạnh tiêu diệt hoàn toàn mọi vi khuẩn trong thực phẩm","Không khí trong tủ lạnh làm thực phẩm khô hoàn toàn","Ánh sáng trong tủ lạnh diệt được nấm mốc"],"a":"Nhiệt độ thấp làm chậm sự phát triển của vi sinh vật gây hỏng thực phẩm","h":"Vi sinh vật phát triển mạnh ở nhiệt độ ấm, chậm lại khi lạnh.","e":"Ở nhiệt độ thấp, hoạt động của vi sinh vật và các enzim gây ôi thiu bị ức chế mạnh nên thực phẩm giữ được lâu hơn, tuy nhiên bảo quản lạnh không tiêu diệt hoàn toàn vi sinh vật.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi bảo quản đông lạnh thực phẩm trong ngăn đá tủ lạnh, nhiệt độ cần đạt mức nào?","o":["Khoảng 10°C","Khoảng 5°C","Dưới 0°C, thường khoảng -18°C","Khoảng 0°C là đủ"],"a":"Dưới 0°C, thường khoảng -18°C","h":"Nước trong thực phẩm phải đóng băng hoàn toàn mới bảo quản được lâu dài.","e":"Bảo quản đông lạnh yêu cầu nhiệt độ dưới 0°C (thường khoảng -18°C) để nước trong thực phẩm đóng băng, vi sinh vật ngừng phát triển, giúp giữ thực phẩm trong thời gian dài.","t":"cn-lop9","g":9,"l":"thu-thach"},{"p":"Để đảm bảo an toàn vệ sinh thực phẩm, trước khi chế biến thức ăn người nấu cần làm gì?","o":["Nếm thử thực phẩm sống để kiểm tra vị","Đeo găng tay vải mỏng là đủ, không cần rửa tay","Dùng chung thớt cho thịt sống và rau ăn sống","Rửa tay sạch bằng xà phòng, giữ dụng cụ và nơi chế biến sạch sẽ"],"a":"Rửa tay sạch bằng xà phòng, giữ dụng cụ và nơi chế biến sạch sẽ","h":"Đây là yêu cầu vệ sinh cá nhân cơ bản nhất trong chế biến thực phẩm.","e":"Rửa tay bằng xà phòng trước khi chế biến và giữ vệ sinh dụng cụ, bề mặt tiếp xúc giúp hạn chế vi khuẩn từ tay và môi trường nhiễm vào thức ăn.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Hành động nào sau đây đúng với nguyên tắc an toàn vệ sinh thực phẩm?","o":["Ăn thử thực phẩm đã có mùi ôi để kiểm tra","Không sử dụng thực phẩm đã ôi thiu, mốc hoặc hết hạn sử dụng","Để thức ăn đã nấu chín ngoài trời qua đêm rồi ăn tiếp","Dùng lại dầu ăn đã chiên nhiều lần cho đến khi hết"],"a":"Không sử dụng thực phẩm đã ôi thiu, mốc hoặc hết hạn sử dụng","h":"Thực phẩm hỏng chứa độc tố của vi sinh vật, đun nóng lại cũng không an toàn.","e":"Thực phẩm ôi thiu, mốc, hết hạn chứa vi sinh vật và độc tố gây bệnh; dù nấu lại cũng không loại bỏ hết độc tố nên tuyệt đối không sử dụng.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Thịt, cá tươi sống mua về chưa chế biến ngay thì nên bảo quản như thế nào?","o":["Để ở nhiệt độ phòng cho ráo nước","Bọc trong giấy báo để trên bàn bếp","Cho vào hộp kín, bảo quản ở ngăn mát hoặc ngăn đá tủ lạnh","Ngâm trong nước lã đến khi cần dùng"],"a":"Cho vào hộp kín, bảo quản ở ngăn mát hoặc ngăn đá tủ lạnh","h":"Thực phẩm tươi sống rất dễ nhiễm khuẩn ở nhiệt độ phòng.","e":"Thịt, cá tươi cần được đựng trong hộp kín và cất vào tủ lạnh (ngăn mát nếu dùng sớm, ngăn đá nếu để lâu) để hạn chế vi sinh vật phát triển và tránh lây nhiễm chéo sang thực phẩm khác.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Nhóm nghề nào sau đây thuộc lĩnh vực kĩ thuật, công nghệ?","o":["Kĩ sư điện, kĩ sư cơ khí, kĩ thuật viên vận hành máy","Bác sĩ, y tá, dược sĩ","Giáo viên, nhà báo, luật sư","Kế toán, nhân viên ngân hàng, thủ quỹ"],"a":"Kĩ sư điện, kĩ sư cơ khí, kĩ thuật viên vận hành máy","h":"Hãy chọn nhóm nghề gắn với máy móc, thiết bị và quy trình kĩ thuật.","e":"Lĩnh vực kĩ thuật, công nghệ gồm các nghề như kĩ sư cơ khí, kĩ sư điện - điện tử, kĩ thuật viên sửa chữa, vận hành thiết bị, lập trình viên... liên quan trực tiếp đến máy móc và công nghệ.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Phẩm chất nào đặc biệt quan trọng đối với người lao động trong lĩnh vực kĩ thuật, công nghệ?","o":["Thích làm việc tuỳ hứng, không theo quy trình","Chỉ cần sức khoẻ tốt, không cần tính cẩn thận","Hay thay đổi công việc để tránh nhàm chán","Cẩn thận, chính xác và tuân thủ nghiêm quy định an toàn lao động"],"a":"Cẩn thận, chính xác và tuân thủ nghiêm quy định an toàn lao động","h":"Công việc kĩ thuật gắn với máy móc và điện, sai sót nhỏ có thể gây hậu quả lớn.","e":"Người làm nghề kĩ thuật, công nghệ phải cẩn thận, tỉ mỉ, chính xác và tuân thủ quy trình, nhất là quy định an toàn lao động, vì công việc liên quan đến máy móc, thiết bị và nguồn năng lượng nguy hiểm.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Năng lực nào sau đây là yêu cầu cơ bản của người làm việc trong lĩnh vực kĩ thuật, công nghệ?","o":["Khả năng ghi nhớ nhiều bài thơ, văn mẫu","Khả năng đọc hiểu bản vẽ kĩ thuật và vận hành, sử dụng thiết bị, máy móc","Khả năng thuyết trình trước đám đông về lịch sử","Khả năng vẽ tranh nghệ thuật đẹp"],"a":"Khả năng đọc hiểu bản vẽ kĩ thuật và vận hành, sử dụng thiết bị, máy móc","h":"Bản vẽ kĩ thuật là 'ngôn ngữ' chung của người làm kĩ thuật.","e":"Người lao động kĩ thuật cần có tư duy kĩ thuật, đọc hiểu được bản vẽ, sơ đồ và biết vận hành, bảo dưỡng máy móc, thiết bị đúng quy trình.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi thu hoạch quả, cần chú ý điều gì để đảm bảo chất lượng sản phẩm?","o":["Thu hoạch càng sớm càng tốt, quả còn xanh cũng hái","Dùng sào rung mạnh cho quả rơi xuống đất","Thu hoạch đúng độ chín, hái nhẹ nhàng, tránh làm dập nát quả","Hái quả vào giữa trưa nắng gắt để quả nhanh khô"],"a":"Thu hoạch đúng độ chín, hái nhẹ nhàng, tránh làm dập nát quả","h":"Quả bị dập sẽ nhanh thối hỏng và giảm giá trị thương phẩm.","e":"Thu hoạch đúng độ chín giúp quả đạt chất lượng và hương vị tốt nhất; thao tác nhẹ nhàng, tránh dập nát giúp quả bảo quản được lâu và bán được giá cao.","t":"cn-lop9","g":9,"l":"nhe-nhang"}];